import { describe, expect, it } from 'vitest';

import claimFixture from './__fixtures__/claim-box.json';
import inboxPriya from './__fixtures__/inbox-priya.json';
import inboxSam from './__fixtures__/inbox-sam.json';
import residentsFixture from './__fixtures__/residents.json';
import { isInbox, isResidentList, isVisitCard } from './types';

// Fixtures are generated by `porch echo-fixtures` from the real MCP tools;
// a backend drift test fails if they go stale.

describe('type guards accept real tool output', () => {
  it('parses anything_for_me structured content', () => {
    expect(isInbox(inboxPriya)).toBe(true);
    expect(isInbox(inboxSam)).toBe(true);
  });

  it('parses the wrapped residents list', () => {
    expect(isResidentList(residentsFixture.result)).toBe(true);
  });

  it('parses claim_box output as a VisitCard', () => {
    expect(isVisitCard(claimFixture)).toBe(true);
  });
});

describe('type guards reject malformed output', () => {
  it('rejects inbox without spoken', () => {
    expect(isInbox({ items: [] })).toBe(false);
  });

  it('rejects inbox with a malformed item', () => {
    expect(isInbox({ spoken: 'hi', items: [{ id: 'x' }] })).toBe(false);
  });

  it('rejects cards with wrong field types', () => {
    const card = { ...inboxPriya.items[0], facts: 'not-an-array' };
    expect(isVisitCard(card)).toBe(false);
    expect(isVisitCard({ ...inboxPriya.items[0], version: '3' })).toBe(false);
  });

  it('rejects residents with missing display name', () => {
    expect(isResidentList([{ id: 'priya' }])).toBe(false);
  });
});
